INSERT INTO `tema` VALUES (1,'La Constitución española de 1978','Bloque I - Tema 1. La Constitución española de 1978: título preliminar, título I (excepto el capítulo III 3º), título II, título III (excepto los capítulos II e III), título IV, título V y título VIII.','activo',1),(2,'Ley 39/2015 - LPAC','Bloque II - Tema 1. Ley 39/2015, de 1 de octubre, del procedimiento administrativo común de las administraciones públicas: títulos preliminar, I, II, III, IV y V.\n','activo',1),(3,'Ley 40/2015 - RJSP','Bloque II - Tema 2. Ley 40/2015, de 1 de octubre, de régimen jurídico del sector público: capítulos I, II (excepto la subsección 2ª de la sección 3ª), III, IV y V del título preliminar.','activo',1),(4,'Ley 2/2015 - Empleo Público','Bloque II - Tema 6. Ley 2/2015, de 29 de abril, del empleo público de Galicia: títulos I al IX.','activo',1),(5,'RDL 1/2013 - LGDPCD','Bloque II - Tema 8. Real decreto legislativo 1/2013, de 29 de noviembre, por el que se aprueba el texto refundido de la Ley general de derechos de las personas con discapacidad y de su inclusión social: título preliminar, título I (sección 1ª del capítulo V y capítulo VIII) y título II.','activo',1),(6,'Ley 1/2016 - LTBG','Bloque II - Tema 9. Ley 1/2016, de 18 de enero, de transparencia y buen gobierno: título preliminar, título I (capítulos I, II, IV, V) y título II (secciones 1ª, 2ª y 3ª del capítulo I).','activo',1),(7,'DL 2/2015 - Igualdad','Bloque II - Tema 10. Ley 7/2023, de 30 de noviembre, para la igualdad efectiva de mujeres y hombres de Galicia: títulos preliminar, I, II (capítulos I, II, y XI), VII y VIII.\n* Anteriormente DL 2/2015','activo',1),(8,'LO 1/1981 - Estatuto de Autonomía','Bloque I - Tema 2. Ley orgánica 1/1981, de 6 de abril, del Estatuto de autonomía para Galicia: título preliminar, título I, título II, título III y título V.','activo',1),(9,'UE - Fuentes del derecho','Bloque I - Tema 3. La Unión Europea, el derecho derivado: reglamentos, directivas, decisiones, recomendaciones y dictámenes.\nTema 4. Fuentes del derecho europeo: actos jurídicos de la Unión, procedimientos de adopción y otras disposiciones según el Tratado de funcionamiento de la Unión Europea. La integración del derecho europeo en España.			\nTema 5. Las instituciones de la Unión Europea: el Parlamento, el Consejo Europeo, el Consejo y la Comisión. Otras instituciones.','activo',1),(10,'Ley 31/1995 - PRL','Bloque I - Tema 7. Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales: capítulo III.','activo',1),(11,'Ley 16/2010 - LOFAXGA','Bloque II - Tema 3. Ley 16/2010, de 17 de diciembre, de organización y funcionamiento de la Administración general y del sector público autonómico de Galicia: títulos preliminar, I, II y capítulo I del título III.','activo',1),(12,'Ley 9/2017 - Contratos','Bloque II - Tema 4. Ley 9/2017, de 8 de noviembre, de contratos del sector público, por la que se trasponen al ordenamiento jurídico español las directivas del Parlamento Europeo y del Consejo 2014/23/UE y 2014/24/UE, de 26 de febrero: título preliminar, libro primero (excepto el capítulo V del título I) y capítulo I del título I (excepto la subsección 5, 6 y 7 de la sección 2) del libro segundo.','activo',1),(13,'Ley 9/2007 - Subvenciones','Bloque II - Tema 5. Ley 9/2007, de 13 de junio, de subvenciones de Galicia: títulos preliminar e I.','activo',1),(14,'DL 1/1999 - LRFPG','Bloque II - Tema 7. Decreto legislativo 1/1999, de 7 de octubre, por el que se aprueba el texto refundido de la Ley de régimen financiero y presupuestario de Galicia: título preliminar y capítulos I y III del título III.','activo',1),(15,'RDL 2/2015 - Estatuto Trabajadores','Bloque II - Tema 11. Real decreto legislativo 2/2015, de 23 de octubre, por el que se aprueba el texto refundido de la Ley del Estatuto de los trabajadores: capítulo I (sección 4ª), capítulo II (secciones 1ª y 2ª) y capítulo III (sección 1ª) del título I.','activo',1),(16,'RDL 8/2015 - LGSS','Bloque II - Tema 12. Real decreto legislativo 8/2015, de 30 de octubre, por el que se aprueba el texto refundido de la Ley general de la seguridad social: capítulos II (sección 1ª), III (sección 1ª) y IV (sección 1ª) del título I, capítulo XI (excepto los artículos 196 la 199) del título II y capítulo I (sección 1ª) del título VI.','activo',1),(17,'C1 Ingreso 2021 covid',NULL,'eliminado',1),(18,'C2 Estabilizacion 2024',NULL,'eliminado',1),(20,'nuevo_tema_usu_premium','dsdasdasdada','activo',4),(22,'nuevo_tema_usuario_free 2','creacion de nuevo_tema_usuario_free para comprobar casos de uso aaaaaaa','activo',3);
